// Turns off GWP-ASan, Android's sampled memory checker, for the app. On Android 14 about one
// launch in ten crashed inside Hermes while GWP-ASan was recording a stack trace: the checker's
// own work, not a fault in the app. android/ is generated by expo prebuild and app.json has no
// setting for it, so the attribute goes on <application> in here.
const { withAndroidManifest } = require("expo/config-plugins");

const ATTRIBUTE = "android:gwpAsanMode";

/** Sets android:gwpAsanMode="never" on the manifest's <application>, whatever it was before. */
function turnOffGwpAsan(manifest) {
  const application = manifest.manifest?.application?.[0];
  if (!application) {
    throw new Error("withGwpAsanOff: AndroidManifest.xml has no <application>, so GWP-ASan can't be turned off.");
  }
  application.$ = { ...application.$, [ATTRIBUTE]: "never" };
  return manifest;
}

function withGwpAsanOff(config) {
  return withAndroidManifest(config, (config) => {
    config.modResults = turnOffGwpAsan(config.modResults);
    return config;
  });
}

module.exports = withGwpAsanOff;
module.exports.turnOffGwpAsan = turnOffGwpAsan;
